public static class WindowsBatteryTests {
 static int checks;
 const string Identity="FAKE_BATTERY_INSTANCE_PRIVATE_MARKER";
 sealed class Fake : IWindowsBatteryBackend {
  public WindowsBatteryPowerStatus System=new WindowsBatteryPowerStatus{AcLineStatus=1,BatteryFlag=8,BatteryLifePercent=75,SystemStatusFlag=0,BatteryLifeTime=UInt32.MaxValue,BatteryFullLifeTime=UInt32.MaxValue};
  public readonly Dictionary<WindowsBatteryDataKind,IList<WindowsBatteryInputRow>> Data=new Dictionary<WindowsBatteryDataKind,IList<WindowsBatteryInputRow>>();
  public readonly Dictionary<WindowsBatteryDataKind,Exception> Errors=new Dictionary<WindowsBatteryDataKind,Exception>();
  public int SystemReads,Queries;public Exception SystemError;
  public readonly List<TimeSpan> Timeouts=new List<TimeSpan>();public readonly List<int> Limits=new List<int>();
  public WindowsBatteryPowerStatus ReadSystemStatus(){SystemReads++;if(SystemError!=null)throw SystemError;return System;}
  public IList<WindowsBatteryInputRow> Query(WindowsBatteryDataKind kind,TimeSpan timeout,int maximumRows){Queries++;Timeouts.Add(timeout);Limits.Add(maximumRows);Exception error;if(Errors.TryGetValue(kind,out error))throw error;IList<WindowsBatteryInputRow> rows;return Data.TryGetValue(kind,out rows)?rows:new List<WindowsBatteryInputRow>();}
 }
 static void Check(bool good,string message){checks++;if(!good)throw new Exception(message);}
 static Dictionary<string,object> Values(params object[] entries){var values=new Dictionary<string,object>(StringComparer.Ordinal);for(int i=0;i<entries.Length;i+=2)values[(string)entries[i]]=entries[i+1];return values;}
 static WindowsBatteryInputRow Row(string name,params object[] entries){return new WindowsBatteryInputRow(name,Values(entries));}
 static Fake Battery(){
  var f=new Fake();f.Data[WindowsBatteryDataKind.Status]=new List<WindowsBatteryInputRow>{Row(Identity,"Active",true,"Tag",1u,"PowerOnline",true,"Charging",true,"Discharging",false,"Critical",false,"RemainingCapacity",13000u,"Voltage",11000u,"ChargeRate",32000,"DischargeRate",0)};
  f.Data[WindowsBatteryDataKind.StaticData]=new List<WindowsBatteryInputRow>{Row(Identity,"Active",true,"Tag",1u,"Capabilities",WindowsBatteryReader.SystemBatteryFlag,"DesignedCapacity",50000u,"SerialNumber","FAKE_SERIAL_NEVER_EXPORT")};
  f.Data[WindowsBatteryDataKind.FullChargedCapacity]=new List<WindowsBatteryInputRow>{Row(Identity,"Active",true,"Tag",1u,"FullChargedCapacity",52000u)};
  f.Data[WindowsBatteryDataKind.CycleCount]=new List<WindowsBatteryInputRow>{Row(Identity,"Active",true,"Tag",1u,"CycleCount",158u)};return f;
 }
 static WindowsBatteryRecord One(WindowsBatterySnapshot snapshot){Check(snapshot.Batteries.Count==1,"one active system battery");return snapshot.Batteries[0];}
 static void Put(Fake f,WindowsBatteryDataKind kind,params object[] fields){f.Data[kind]=new List<WindowsBatteryInputRow>{Row(Identity,fields)};}
 static bool Near(double? value,double expected){return value.HasValue&&Math.Abs(value.Value-expected)<0.000001;}
 static void Pure(){
  var f=Battery();var reader=new WindowsBatteryReader(f);Check(f.SystemReads==0&&f.Queries==0,"constructor has no native or WMI I/O");var s=reader.ReadSnapshot();var b=One(s);
  Check(s.HasSystemBattery==true&&s.AcOnline==true&&s.Charging==true&&s.ChargePercent==75,"documented aggregate fields");Check(b.DesignedCapacityMilliwattHours==50000&&b.FullChargedCapacityMilliwattHours==52000&&b.RemainingCapacityMilliwattHours==13000,"energy values retained in mWh");Check(b.VoltageMillivolts==11000&&b.ChargeRateMilliwatts==32000&&Near(b.SignedPowerMilliwatts,32000),"voltage mV and power mW are separate");Check(Near(b.HealthPercent,104)&&Near(b.ChargePercent,25),"health may exceed 100 and per-cell charge is separate from aggregate");Check(b.CycleCount==158&&!b.StateConflict&&b.MetadataConsistent&&b.RelativeCapacityUnits==false&&b.IsSystemBattery==true,"cycle and metadata status");Check(b.StableId.Length==64&&b.StableId.All(c=>c>='0'&&c<='9'||c>='a'&&c<='f'),"SHA256 public identity");Check(f.Queries==4&&f.SystemReads==1&&f.Timeouts.All(t=>t>TimeSpan.Zero&&t<=TimeSpan.FromSeconds(2))&&f.Limits.All(l=>l==128),"query count, time and row bounds");
  var json=new JavaScriptSerializer().Serialize(s);Check(!json.Contains(Identity)&&!json.Contains("FAKE_SERIAL_NEVER_EXPORT")&&!json.Contains("InstanceName")&&!json.Contains("SerialNumber"),"snapshot never exposes instance or serial");Check(new JavaScriptSerializer().Serialize(f.Data[WindowsBatteryDataKind.StaticData][0])=="{}","backend row serialization cannot expose private inputs");Check(reader.ReadSnapshot().Batteries[0].StableId==b.StableId,"identity stable between reads");
  for(int percent=0;percent<=255;percent++){f=new Fake();f.System.BatteryFlag=0;f.System.BatteryLifePercent=(byte)percent;s=new WindowsBatteryReader(f).ReadSnapshot();Check(percent<=100?s.ChargePercent==percent:!s.ChargePercent.HasValue,"aggregate percent range "+percent);}
  f=new Fake();f.System.BatteryLifePercent=0;s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.ChargePercent==0,"zero percent is valid");
  f=new Fake();f.System.BatteryFlag=255;f.System.BatteryLifePercent=255;f.System.AcLineStatus=255;f.System.SystemStatusFlag=255;s=new WindowsBatteryReader(f).ReadSnapshot();Check(!s.HasSystemBattery.HasValue&&!s.Charging.HasValue&&!s.Critical.HasValue&&!s.ChargePercent.HasValue&&!s.AcOnline.HasValue&&!s.BatterySaver.HasValue,"255 means unknown before bit tests");
  f=Battery();f.System.BatteryFlag=128;f.System.BatteryLifePercent=0;s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.HasSystemBattery==false&&s.Batteries.Count==0&&!s.ChargePercent.HasValue&&f.Queries==0,"no system battery cannot become peripheral WMI battery");
  f=Battery();f.System.BatteryFlag=129;s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.HasSystemBattery==false&&s.Batteries.Count==0,"no-battery bit has precedence in combined flags");
  f=new Fake();f.System.BatteryFlag=0;f.System.AcLineStatus=0;f.System.BatteryLifeTime=0;f.System.BatteryFullLifeTime=0;s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.RemainingSeconds==0&&s.FullLifeSeconds==0&&s.AcOnline==false,"zero lifetime seconds retained on DC");f.System.BatteryLifeTime=UInt32.MaxValue;f.System.BatteryFullLifeTime=UInt32.MaxValue;s=new WindowsBatteryReader(f).ReadSnapshot();Check(!s.RemainingSeconds.HasValue&&!s.FullLifeSeconds.HasValue,"lifetime sentinel omitted");f.System.BatteryLifeTime=50;f.System.AcLineStatus=1;s=new WindowsBatteryReader(f).ReadSnapshot();Check(!s.RemainingSeconds.HasValue,"AC does not claim battery depletion estimate");
  f=Battery();Put(f,WindowsBatteryDataKind.StaticData,"Active",true,"Tag",1u,"Capabilities",WindowsBatteryReader.SystemBatteryFlag|WindowsBatteryReader.RelativeCapacityFlag,"DesignedCapacity",100u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.RelativeCapacityUnits==true&&!b.DesignedCapacityMilliwattHours.HasValue&&!b.FullChargedCapacityMilliwattHours.HasValue&&!b.RemainingCapacityMilliwattHours.HasValue&&!b.ChargeRateMilliwatts.HasValue&&!b.SignedPowerMilliwatts.HasValue&&!b.HealthPercent.HasValue,"relative units cannot be mislabeled mWh or mW");Check(b.VoltageMillivolts==11000,"relative energy does not convert voltage");
  f=Battery();Put(f,WindowsBatteryDataKind.StaticData,"Active",true,"Tag",1u,"DesignedCapacity",50000u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(!b.RelativeCapacityUnits.HasValue&&!b.DesignedCapacityMilliwattHours.HasValue&&!b.FullChargedCapacityMilliwattHours.HasValue&&!b.SignedPowerMilliwatts.HasValue,"missing capability cannot assume absolute units");
  f=Battery();Put(f,WindowsBatteryDataKind.StaticData,"Active",true,"Capabilities",0u,"DesignedCapacity",50000u);Check(new WindowsBatteryReader(f).ReadSnapshot().Batteries.Count==0,"explicit non-system battery excluded");
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"Charging",false,"Discharging",true,"PowerOnline",true,"DischargeRate",20500,"ChargeRate",0,"RemainingCapacity",0u,"Voltage",0u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.PowerOnline==true&&b.Discharging==true&&!b.StateConflict&&b.DischargeRateMilliwatts==20500&&Near(b.SignedPowerMilliwatts,-20500),"discharge may occur with AC online and sign remains discharge");Check(b.RemainingCapacityMilliwattHours==0&&b.VoltageMillivolts==0&&Near(b.ChargePercent,0),"reported zero remains zero");
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"Charging",true,"Discharging",true,"ChargeRate",32000,"DischargeRate",25000);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.StateConflict&&!b.SignedPowerMilliwatts.HasValue&&!b.ChargeRateMilliwatts.HasValue&&!b.DischargeRateMilliwatts.HasValue,"contradictory state provides no power");
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"Charging",true,"ChargeRate",32000);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(!b.Discharging.HasValue&&!b.SignedPowerMilliwatts.HasValue,"missing direction flag remains unknown");
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"Charging",false,"Discharging",false,"ChargeRate",0,"DischargeRate",0);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(Near(b.SignedPowerMilliwatts,0)&&b.ChargeRateMilliwatts==0&&b.DischargeRateMilliwatts==0,"confirmed idle zero power");
  foreach(object sentinel in new object[]{UInt32.MaxValue,4294967295L,-1,Int32.MinValue,2147483648u,Double.NaN,Double.PositiveInfinity,true,12.5m}){f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"Charging",true,"Discharging",false,"ChargeRate",sentinel);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(!b.ChargeRateMilliwatts.HasValue&&!b.SignedPowerMilliwatts.HasValue,"power sentinel or incompatible type omitted");}
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"RemainingCapacity",UInt32.MaxValue,"Voltage",UInt32.MaxValue);Put(f,WindowsBatteryDataKind.StaticData,"Active",true,"Tag",1u,"Capabilities",WindowsBatteryReader.SystemBatteryFlag,"DesignedCapacity",UInt32.MaxValue);Put(f,WindowsBatteryDataKind.FullChargedCapacity,"Active",true,"Tag",1u,"FullChargedCapacity",UInt32.MaxValue);Put(f,WindowsBatteryDataKind.CycleCount,"Active",true,"Tag",1u,"CycleCount",UInt32.MaxValue);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(!b.DesignedCapacityMilliwattHours.HasValue&&!b.FullChargedCapacityMilliwattHours.HasValue&&!b.RemainingCapacityMilliwattHours.HasValue&&!b.VoltageMillivolts.HasValue&&!b.CycleCount.HasValue&&!b.HealthPercent.HasValue,"all-ones sentinel omitted in telemetry");
  f=Battery();Put(f,WindowsBatteryDataKind.StaticData,"Active",true,"Tag",1u,"Capabilities",WindowsBatteryReader.SystemBatteryFlag,"DesignedCapacity",0u);Put(f,WindowsBatteryDataKind.CycleCount,"Active",true,"Tag",1u,"CycleCount",0u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.DesignedCapacityMilliwattHours==0&&!b.HealthPercent.HasValue&&!b.CycleCount.HasValue,"zero denominator and unsupported zero cycle counter never manufactured");
  f=Battery();Put(f,WindowsBatteryDataKind.FullChargedCapacity,"Active",true,"Tag",1u,"FullChargedCapacity",0u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.FullChargedCapacityMilliwattHours==0&&Near(b.HealthPercent,0)&&!b.ChargePercent.HasValue,"zero full capacity does not divide by zero");
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",1u,"RemainingCapacity",60000u);b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(b.RemainingCapacityMilliwattHours==60000&&!b.ChargePercent.HasValue,"inconsistent over-full remaining amount not clamped into invented percent");
  f=Battery();Put(f,WindowsBatteryDataKind.FullChargedCapacity,"Active",true,"Tag",2u,"FullChargedCapacity",52000u);s=new WindowsBatteryReader(f).ReadSnapshot();b=One(s);Check(!b.MetadataConsistent&&!b.FullChargedCapacityMilliwattHours.HasValue&&!b.HealthPercent.HasValue&&s.Errors.Any(e=>e.Category=="BatteryTagChanged"),"changed battery tag never merges stale full capacity");
  f=Battery();f.Data[WindowsBatteryDataKind.FullChargedCapacity]=new List<WindowsBatteryInputRow>{Row(Identity.ToLowerInvariant(),"Active",true,"Tag",1u,"FullChargedCapacity",10000u)};b=One(new WindowsBatteryReader(f).ReadSnapshot());Check(!b.FullChargedCapacityMilliwattHours.HasValue,"instance merge is exact, not case-folded");
  f=Battery();f.Data[WindowsBatteryDataKind.Status].Add(f.Data[WindowsBatteryDataKind.Status][0]);s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.Batteries.Count==0&&s.Errors.Any(e=>e.Category=="AmbiguousIdentity"),"duplicate active identities are rejected");
  f=Battery();f.Data[WindowsBatteryDataKind.StaticData].Add(f.Data[WindowsBatteryDataKind.StaticData][0]);s=new WindowsBatteryReader(f).ReadSnapshot();b=One(s);Check(!b.DesignedCapacityMilliwattHours.HasValue&&!b.SignedPowerMilliwatts.HasValue&&s.Errors.Any(e=>e.Category=="AmbiguousIdentity"),"ambiguous unit metadata omitted");
  foreach(object active in new object[]{false,null,1,"true"}){f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",active,"Tag",1u);Check(new WindowsBatteryReader(f).ReadSnapshot().Batteries.Count==0,"unconfirmed current status not instantiated");}
  f=Battery();Put(f,WindowsBatteryDataKind.Status,"Active",true,"Tag",0u);Check(new WindowsBatteryReader(f).ReadSnapshot().Batteries.Count==0,"zero battery tag is not a current pack");
  foreach(string bad in new[]{"",null," ","\ninvalid",new string('x',2049)}){f=Battery();f.Data[WindowsBatteryDataKind.Status]=new List<WindowsBatteryInputRow>{Row(bad,"Active",true,"Tag",1u)};s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.Batteries.Count==0&&s.Errors.Any(e=>e.Category=="InvalidIdentity"),"invalid identity rejected without source leak");}
  f=Battery();f.Data[WindowsBatteryDataKind.Status].Add(Row("FAKE_SECOND_BATTERY", "Active",true,"Tag",1u));s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.Batteries.Count==2&&s.Batteries.Select(x=>x.StableId).Distinct().Count()==2,"different exact current identities remain separate");Check(s.Batteries.Single(x=>x.StableId!=new WindowsBatteryReader(Battery()).ReadSnapshot().Batteries[0].StableId).DesignedCapacityMilliwattHours==null,"first battery metadata never borrowed by second");
  f=Battery();f.Errors[WindowsBatteryDataKind.StaticData]=new InvalidOperationException(Identity+" FAKE_SERIAL_NEVER_EXPORT");s=new WindowsBatteryReader(f).ReadSnapshot();b=One(s);Check(!b.DesignedCapacityMilliwattHours.HasValue&&b.VoltageMillivolts==11000&&s.Errors.Count==1,"one provider failure retains independent voltage and current identity");json=new JavaScriptSerializer().Serialize(s);Check(!json.Contains(Identity)&&!json.Contains("FAKE_SERIAL_NEVER_EXPORT")&&s.Errors[0].HResult.HasValue,"error metadata does not leak native exception text");
  f=Battery();f.Errors[WindowsBatteryDataKind.Status]=new TimeoutException(Identity);s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.Batteries.Count==0&&s.Errors.Single().Category=="Timeout"&&f.Queries==1&&s.ChargePercent==75,"status timeout leaves only real aggregate data");
  f=Battery();f.SystemError=new System.ComponentModel.Win32Exception(5);s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.HasSystemBattery==null&&s.Batteries.Count==1&&s.Errors.Any(e=>e.Source=="GetSystemPowerStatus"&&e.NativeErrorCode==5),"failed aggregate read does not suppress valid provider readings");
  f=Battery();f.Data[WindowsBatteryDataKind.Status]=Enumerable.Range(0,129).Select(i=>Row("FAKE_LIMIT_"+i,"Active",true,"Tag",1u)).ToList();s=new WindowsBatteryReader(f).ReadSnapshot();Check(s.Batteries.Count==0&&s.Errors.Any(e=>e.Category=="InvalidData"),"oversized provider result rejected");
  Check(typeof(IWindowsBatteryBackend).GetMethods().All(m=>m.Name=="ReadSystemStatus"||m.Name=="Query"),"backend offers no battery setter");
  var native=new WindowsBatteryNativeBackend();bool rejected=false;try{native.Query(WindowsBatteryDataKind.Status,TimeSpan.Zero,128);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected,"native zero timeout rejected before I/O");rejected=false;try{native.Query(WindowsBatteryDataKind.Status,TimeSpan.FromSeconds(3),128);}catch(ArgumentOutOfRangeException){rejected=true;}Check(rejected,"native unbounded timeout rejected before I/O");
  var gateMethod=typeof(WindowsBatteryNativeBackend).GetMethod("SharedQueryGate",BindingFlags.Static|BindingFlags.NonPublic);var gate=(SemaphoreSlim)gateMethod.Invoke(null,null);Check(gate.Wait(0),"reserve fake pending query without WMI");
  try{
   var first=new WindowsBatteryReader(new Fake());var second=new WindowsBatteryReader(new Fake());Check(first!=null&&second!=null,"two readers construct while another query is pending");
   foreach(var backend in new[]{new WindowsBatteryNativeBackend(),new WindowsBatteryNativeBackend()}){bool blocked=false;try{backend.Query(WindowsBatteryDataKind.Status,TimeSpan.FromMilliseconds(20),128);}catch(TimeoutException){blocked=true;}Check(blocked&&gate.CurrentCount==0,"second backend cannot overlap or release pending query");}
   var loaded=Assembly.Load(File.ReadAllBytes(Assembly.GetExecutingAssembly().Location));var loadedBackendType=loaded.GetType("RogControl.WindowsBatteryNativeBackend",true);var loadedGate=(SemaphoreSlim)loadedBackendType.GetMethod("SharedQueryGate",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);Check(Object.ReferenceEquals(gate,loadedGate),"byte-loaded replacement assembly shares System gate");
   var backendCopy=Activator.CreateInstance(loadedBackendType);var kindCopy=Enum.ToObject(loaded.GetType("RogControl.WindowsBatteryDataKind",true),0);bool copyBlocked=false;try{loadedBackendType.GetMethod("Query").Invoke(backendCopy,new object[]{kindCopy,TimeSpan.FromMilliseconds(20),128});}catch(TargetInvocationException ex){copyBlocked=ex.InnerException is TimeoutException;}Check(copyBlocked&&gate.CurrentCount==0,"replacement payload cannot query or release old pending provider");
  }finally{gate.Release();}
  Check(gate.CurrentCount==1,"only the simulated query completion releases the gate");
  Console.WriteLine("Windows battery: "+checks+" pure fake checks passed; no native GET, WMI query, charge setter, driver install or elevation.");
 }
 static void ReadOnly(string path){var s=new WindowsBatteryReader().ReadSnapshot();if(!String.IsNullOrWhiteSpace(path))File.WriteAllText(path,new JavaScriptSerializer().Serialize(s));Console.WriteLine("Read-only Windows battery snapshot: presence="+(s.HasSystemBattery.HasValue?s.HasSystemBattery.Value.ToString():"unknown")+", AC="+(s.AcOnline.HasValue?s.AcOnline.Value.ToString():"unknown")+", battery records="+s.Batteries.Count+", aggregate percent="+(s.ChargePercent.HasValue?s.ChargePercent.Value.ToString(CultureInfo.InvariantCulture):"unknown")+", source errors="+s.Errors.Count+"; no setters.");}
 public static int Main(string[] args){try{if(args.Length>0&&args[0]=="--read-only"){if(args.Length>2)throw new ArgumentException("Unexpected argument.");ReadOnly(args.Length==2?args[1]:null);}else{if(args.Length>0)throw new ArgumentException("Unknown mode.");Pure();}return 0;}catch(Exception ex){Console.Error.WriteLine("Windows battery checks failed after "+checks+": "+ex.GetType().Name+" "+ex.Message);return 1;}}
}
